import sys, numpy as np
L=open(sys.argv[1]).read().strip().split('\n')[2:]
S=[l.split()[0] for l in L]; P=np.array([[float(x) for x in l.split()[1:4]] for l in L])
d=np.linalg.norm(P[:,None]-P[None],axis=2)
print('Ru neighbors',[(j,S[j],round(d[0,j],2)) for j in range(1,len(S)) if d[0,j]<2.6])
# connectivity check for heavy atoms
cov={'C':0.77,'N':0.71,'P':1.07,'H':0.32,'Ru':1.4}
for i,s in enumerate(S):
    if s=='Ru': continue
    nb=[j for j in range(len(S)) if j!=i and S[j]!='Ru' and d[i,j]<1.2*(cov[s]+cov[S[j]])]
    exp={'C':4,'N':3,'P':4,'H':1}
    if s in('C','P') and len(nb)!=exp[s] and not (s=='C' and len(nb)==3): print('odd',i,s,[(j,S[j]) for j in nb])
    if s=='H' and len(nb)!=1: print('odd H',i,[(j,S[j]) for j in nb])
EOF
python check.py step1.xyz; grep -A3 "TOTAL ENERGY" step1.log | head; grep "GRADIENT NORM" step1.log
